-- PT109-S3-Q6. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT109-S3-Q6$batch09$ AND q.stimulus=$batch09$The recent cleaning of frescoes in the Sistine Chapel has raised important asthetic issues. Art historians are now acutely aware that the colors of the works they study may differ from the works’ original colors. Art historians have concluded from this that interpretations of the frescoes that seemed appropriate before the frescoes’ restoration may no longer be appropriate.$batch09$ AND q.prompt=$batch09$Which one of the following principles, if valid, most helps to justify the art historians' reasoning?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT109-S3-Q6$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT109-S3-Q6$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Interpretations of the frescoes that seemed appropriate before the restoration may no longer be appropriate.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The cleaning showed that the colors of the works historians study may differ from the original colors.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The evidence is about colors, and the conclusion is about interpretations. To bridge that gap, colors have to matter to interpretation. If they didn't, a change in color couldn't unsettle anyone's reading of the frescoes.$batch09$), (3, $batch09$Goal$batch09$, $batch09$A principle that says an artwork's colors bear on how it should be interpreted.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT109-S3-Q6$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This ties interpretation to the history of the period when it was made. The evidence is about color, so A doesn't connect.$batch09$), ($batch09$B$batch09$, $batch09$This is the trap, picked by 10%. It's true to the stimulus: restoration can change colors. But that's the premise we already have. B never mentions interpretation, so it doesn't explain why old interpretations might no longer hold.$batch09$), ($batch09$C$batch09$, $batch09$If colors are relevant to an appropriate interpretation, then learning the colors were different gives a reason to doubt interpretations based on the old colors. Evidence about color now reaches the conclusion about interpretation.$batch09$), ($batch09$D$batch09$, $batch09$The argument is about whether interpretations are appropriate, not about who judges an artwork's value.$batch09$), ($batch09$E$batch09$, $batch09$This judges interpretations by when they started. That has nothing to do with the colors changing.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT109-S3-Q6$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
